package ar.com.miflix.admin

import com.google.gson.*
import okhttp3.OkHttpClient
import okhttp3.mockwebserver.*
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.util.concurrent.TimeUnit

@RunWith(RobolectricTestRunner::class)
@Config(sdk=[28],manifest=Config.NONE)
class CollectionTmdbTest {
    private fun obj(raw:String)=JsonParser.parseString(raw).asJsonObject
    private fun details()=obj("""{"id":10,"name":"Saga de prueba","overview":"<p>Descripción &amp; acción</p>","poster_path":"/poster.jpg","backdrop_path":"/back.jpg","parts":[{"id":1,"title":"Uno","release_date":"2001-01-01"},{"id":2,"title":"Dos","release_date":"2002-01-01"},{"id":3,"title":"Tres","release_date":"2003-01-01"}]}""")
    private fun catalog()=obj("""{"schema_version":1,"items":[{"id":"one","tipo":"pelicula","titulo":"Uno","tmdb_id":1},{"id":"one-alt","tipo":"pelicula","titulo":"Una versión","tmdb_id":1},{"id":"series-one","tipo":"serie","titulo":"Uno","tmdb_id":1},{"id":"two","tipo":"pelicula","titulo":"Dos","anio":"2002"},{"id":"wrong","tipo":"pelicula","titulo":"Tres","tmdb_id":44,"anio":"2003"}]}""")
    private fun provider(s:MockWebServer,direct:Boolean=true,timeout:Long=1500)=TmdbCollections(HttpMetadata(AdminConfig(s.url("/").toString().trimEnd('/'),"synthetic-worker",if(direct) "synthetic-tmdb" else ""),OkHttpClient.Builder().callTimeout(timeout,TimeUnit.MILLISECONDS).build(),s.url("/3").toString()))
    private fun server(test:(MockWebServer)->Unit) {val s=MockWebServer();s.start();try {test(s)}finally{s.shutdown()}}
    @Test fun searchUsesOfficialEndpointSpanishAndExistingCredential()=server {s ->s.enqueue(MockResponse().setBody("""{"results":[{"id":10,"name":"Saga"}],"total_pages":2}"""));val r=provider(s).search("Saga á",1,"es-AR");assertEquals(1,r.results.size);assertEquals(2,r.pages);val req=s.takeRequest();assertTrue(req.path!!.startsWith("/3/search/collection?language=es-AR"));assertTrue(req.path!!.contains("query=Saga"));assertEquals("Bearer synthetic-tmdb",req.getHeader("Authorization"))}
    @Test fun searchByIdFetchesCollectionWithoutTextGuessing()=server {s ->s.enqueue(MockResponse().setBody(details().toString()));assertEquals(10L,provider(s).search("10",1,"es-AR").results.single().number("id"));assertEquals("/3/collection/10?language=es-AR",s.takeRequest().path)}
    @Test fun emptySearchAndMultipleCandidatesStayExplicit()=server {s ->s.enqueue(MockResponse().setBody("""{"results":[]}"""));assertTrue(provider(s).search("Absent",1,"es-AR").results.isEmpty());s.enqueue(MockResponse().setBody("""{"results":[{"id":10,"name":"Saga"},{"id":20,"name":"Otra saga"}]}"""));assertEquals(2,provider(s).search("Saga",1,"es-AR").results.size)}
    @Test fun exactMovieIdsDoNotMatchSeriesAndDuplicatesAreAmbiguous() {val rows=CollectionImport.match(details(),catalog());assertEquals(listOf("one","one-alt"),rows[0].exact);assertTrue(rows[0].possible.isEmpty());assertEquals(listOf("two"),rows[1].possible);assertTrue(rows[2].exact.isEmpty());assertTrue(rows[2].possible.isEmpty())}
    @Test fun similarTitleAloneCannotSelectOrMatch() {val c=catalog();c.getAsJsonArray("items").add(obj("""{"id":"similar","tipo":"pelicula","titulo":"Tres parecida","anio":"2003"}"""));assertTrue(CollectionImport.match(details(),c)[2].possible.isEmpty())}
    @Test fun missingMovieNotCreatedAndOnlyConfirmedMembersAdded() {val c=catalog();val snap=c.deepCopy();val d=CollectionRules.fresh().apply{addProperty("nombre","Manual")};val out=CollectionImport.apply(d,details(),emptySet(),setOf("two"),c,"es-AR");assertEquals(listOf("two"),CollectionRules.ids(out));assertEquals(snap,c);assertEquals("Manual",out.text("nombre"))}
    @Test fun selectedMetadataOnlyAndManualOverridesSurviveRequery() {val d=CollectionRules.fresh().apply{addProperty("nombre","Mundo Marvel");addProperty("descripcion","Manual");addProperty("poster_url","https://custom.invalid/a.jpg")};val original=d.deepCopy();val out=CollectionImport.apply(d,details(),setOf("descripcion"),emptySet(),catalog(),"es-AR");assertEquals("Descripción & acción",out.text("descripcion"));assertEquals("Mundo Marvel",out.text("nombre"));assertEquals(d.text("poster_url"),out.text("poster_url"));assertEquals(original,d);val again=CollectionImport.apply(out,details(),emptySet(),emptySet(),catalog(),"es-AR");assertEquals(out,again)}
    @Test fun englishFallbackRequiresExplicitRequestAndSelection()=server {s ->s.enqueue(MockResponse().setBody(details().apply{addProperty("overview","")}.toString()));val p=provider(s);val spanish=p.detail(10,"es-AR");assertEquals("",spanish.text("overview"));assertEquals(1,s.requestCount);s.enqueue(MockResponse().setBody(details().apply{addProperty("overview","English text")}.toString()));val english=p.detail(10,"en-US");assertEquals("English text",english.text("overview"));s.takeRequest();assertEquals("/3/collection/10?language=en-US",s.takeRequest().path)}
    @Test fun unavailableSelectedEmptyFieldCannotEraseManualValue() {val d=CollectionRules.fresh().apply{addProperty("descripcion","Manual")};assertThrows(IllegalArgumentException::class.java){CollectionImport.apply(d,details().apply{addProperty("overview","")},setOf("descripcion"),emptySet(),catalog(),"es-AR")};assertEquals("Manual",d.text("descripcion"))}
    @Test fun collectionWithImagesOffersAllLanguagesAtBoundedSizes()=server {s ->s.enqueue(MockResponse().setBody("""{"id":10,"posters":[{"file_path":"/es.jpg","iso_639_1":"es"},{"file_path":"/en.jpg","iso_639_1":"en"}],"backdrops":[{"file_path":"/back.jpg","iso_639_1":null}]}"""));val images=provider(s).images(10);assertEquals(3,images.size);assertEquals(setOf("es","en","sin idioma"),images.map{it.language}.toSet());assertTrue(images.first().url.contains("/w500/"));assertTrue(images.last().preview.contains("/w780/"));assertEquals("/3/collection/10/images",s.takeRequest().path)}
    @Test fun noArtworkIsNotInvented()=server {s ->s.enqueue(MockResponse().setBody("""{"id":10,"posters":[],"backdrops":[]}"""));assertTrue(provider(s).images(10).isEmpty())}
    @Test fun wrongIdentityOrUnsafeImagePathRejected()=server {s ->s.enqueue(MockResponse().setBody("""{"id":11,"parts":[],"name":"Other"}"""));assertThrows(IllegalStateException::class.java){provider(s).detail(10,"es-AR")};assertFalse(TmdbCollections.validPath("//evil.test/key.jpg"));assertFalse(TmdbCollections.validPath("/../key.jpg"));assertEquals("",TmdbCollections.url("https://evil.test/a.jpg","poster_url"))}
    @Test fun relayUnsupportedGivesActionableExistingConfigMessage()=server {s ->s.enqueue(MockResponse().setResponseCode(400));val m=assertThrows(IllegalStateException::class.java){provider(s,false).detail(10,"es-AR")}.message!!;assertTrue(m.contains("Token local"));assertFalse(m.contains("synthetic-worker"))}
    @Test fun authenticationErrorsAreRedacted()=server {s ->s.enqueue(MockResponse().setResponseCode(401).setBody("synthetic-tmdb"));val m=assertThrows(IllegalStateException::class.java){provider(s).detail(10,"es-AR")}.message!!;assertFalse(m.contains("synthetic"));assertTrue(m.contains("rechazó"))}
    @Test fun timeoutAndRateLimitLeaveInputUntouched()=server {s ->s.enqueue(MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE));assertThrows(IllegalStateException::class.java){provider(s,timeout=150).detail(10,"es-AR")};s.enqueue(MockResponse().setResponseCode(429));assertThrows(IllegalStateException::class.java){provider(s).detail(10,"es-AR")}}
    @Test fun cancellationStopsBeforeAnyRequest()=server {s ->val p=provider(s);p.cancel();assertThrows(IllegalStateException::class.java){p.detail(10,"es-AR")};assertEquals(0,s.requestCount)}
    @Test fun invalidPathLanguageOrPageNeverLeavesClient() {val m=HttpMetadata(AdminConfig("https://worker.invalid","synthetic"));assertThrows(IllegalArgumentException::class.java){m.collectionRequest("https://evil.invalid","es-AR")};assertThrows(IllegalArgumentException::class.java){m.collectionRequest("/collection/10","bad")};assertThrows(IllegalArgumentException::class.java){m.collectionRequest("/search/collection","es-AR","x",0)}}
    @Test fun malformedResponseFailsClearly()=server {s ->s.enqueue(MockResponse().setBody("{}"));assertThrows(IllegalStateException::class.java){provider(s).detail(10,"es-AR")}}
}
